{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Withaferin A, a structurally related complex steroidal lactone, showed poor oral bioavailability in humans; its high transferability to the query supports a low F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Fluticasone, a corticosteroid with a similar fused-ring scaffold, had absolute oral bioavailability <1% via gastrointestinal absorption, directly supporting F<20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Ginsenoside Rg3, a high-molecular-weight glycosylated triterpenoid, showed low oral bioavailability in humans; high transferability reinforces the low prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Rifaximin, a complex polar natural product, had <0.4% oral bioavailability in healthy volunteers, demonstrating that high-transfer complex molecules are consistently low.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Sitostanol, a plant sterol, had absolute oral bioavailability of only 0.04% after oral administration, providing a quantitative anchor far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Docetaxel, a complex diterpenoid, had low absolute oral bioavailability in humans due to first-pass extraction, supporting low F for the query's terpenoid acid scaffold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show low or negligible oral bioavailability in humans. The query's complex terpenoid/steroid-like structure with an ionized carboxylic acid, high molecular weight, and multiple polar groups aligns with these low-bioavailability phenotypes. Therefore, predict low oral bioavailability (F < 20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule itself.",
    "Quantitative F value for the query is not directly measured; prediction relies on qualitative low/poor labels from highly transferable analogues.",
    "Potential differences in specific transporters or metabolic enzymes between the query and analogues are not fully resolved."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

